#include <stdio.h>
/*
 * ex10：命题逻辑的「规模墙」—— 2^n 到底有多快撞墙
 * 为什么：SAT 是第一个被证明 NP 完全的问题，但「NP 完全」只是说没有已知多项式算法，
 *        真正的工程感受来自这张表：n=30 时暴力枚举已经是 10 亿行。
 *        这也解释了为什么实际求解器要 DPLL/CDCL，而不是枚举。
 */
int main(void) {
    printf("%-6s %-22s %-16s %s\n", "n", "assignments 2^n", "at 1e9/s", "clauses (4.26n, 3-SAT)");
    printf("--------------------------------------------------------------\n");
    for (int n = 10; n <= 60; n += 10) {
        double a = 1.0;
        for (int i = 0; i < n; i++) a *= 2.0;
        double sec = a / 1e9;
        printf("%-6d %-22.3e %-16.3e %.0f\n", n, a, sec, 4.26 * n);
    }
    printf("\n");
    printf("n=20   2^20  ~ 1e6      -> brute force is fine\n");
    printf("n=40   2^40  ~ 1e12     -> 11 days at 1e9/s\n");
    printf("n=60   2^60  ~ 1e18     -> 31 years at 1e9/s\n");
    printf("\nkey: 2-SAT has an O(n+m) algorithm because (a v b) becomes two implications,\n");
    printf("     and an implication graph with no (x, ~x) in one SCC is satisfiable.\n");
    printf("     3-SAT has no such structure -- that is exactly why it is NP-complete.\n");
    return 0;
}
